export function videoPeopleDirection(people){
  return people==='none'?'画面中不出现人物和手。':people==='model'?'允许同一位成年模特自然出镜，服装、发型与身份在各镜保持一致；以预先摆好的静坐或侧躺姿态开始，只允许呼吸、眨眼和轻微转头，不拍上床、翻身、起身、拉被盖身或压挤床品，不生成口型表演。':'人物最多只出现自然的手部，不出现脸部与口型；手与床品保持距离，仅作静态陪衬，不触碰、不按压、不推动布面。';
}
export function videoMotionPolicy(people){
  return '【床品稳定与细节拍摄优先规则，覆盖脚本中冲突的动作描述】先分别生成不同角度的静态分镜图，再逐镜展示该角度下的床品细节；15秒通常为三张角度图与三段视频，较长视频增加独立细节角度，不把一镜变成多角度环绕。至少三分之二镜头为花型、枕套、成品边缘或表面纹理的近景/特写；商品占据主要画面，不以房间远景、人物或道具抢戏。被芯、被套、床单、枕套与其他主售床品全程保持已铺放形态、位置、褶皱、图案比例和正反面归属。禁止翻动被芯、翻被、掀被、抖被、揭角、折叠、拉扯、揉搓、掀开反面、抛起枕头或让床品自行飘动；即使脚本或创作要求提到这些动作，也以本规则替代。只用同一角度的小幅缓慢推进、短距离平移或定机拍摄展示不同的细节信息，不环绕、不急转机位、不从正面转背面、不做花型形变和纹理游移。内容通过花型、边缘与搭配的镜间剪辑推进，不靠床品形变推进。'+videoPeopleDirection(people);
}
export function detailCameraPlan(index){
  return [
    {view:'左前侧斜向近景，聚焦主售床品的花型与已铺好的表面，背景仅少量虚化',move:'从左前侧机位沿现有花型小幅缓慢推进，始终保持同一可见面，停留看清图案尺度'},
    {view:'斜俯视近景，观察与上一镜不同的花型局部、配色与表面纹理',move:'保持斜俯视角度，沿布面短距离平移，清晰展示连续花型，布面与褶皱保持静止'},
    {view:'右前侧低机位近景，聚焦真实可见的成品边缘或枕套与被面的连接搭配',move:'从右前侧机位小幅缓慢推进，停留展示边缘与花型关系，不揭开或移动任何部件'},
    {view:'侧向微距特写，观察已确认可见的缝线、边缘及相邻花型',move:'同一侧向机位定机停留，展示可见结构，不拉伸、不拆开、不虚构隐藏工艺'},
    {view:'较高斜侧近景，观察另一处连续花型及同款部件的配色关系',move:'较高斜侧机位短距离平移，维持图案尺度和已铺放状态，不转到反面'},
    {view:'床边斜向中近景，以主售床品细节和少量空间搭配收尾',move:'在同一床边机位缓慢微退，保持商品为主体，以稳定画面停留收尾'},
  ][index%6];
}
